contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function test(uint256 amount1, uint256 amount2) public payable {
        require(amount1 > 0 && amount2 > 0);
        // fund test contract to forward calls
        require(address(this).balance >= amount1 + amount2);

        // simulate two users with high balances to trigger overflow in M
        c.addToBalance{value: amount1}();
        // second call from a different address would need delegation, but since we can't change msg.sender trivially,
        // we use the fact that the invariant must hold after any sequence of calls from any senders.
        // Here we just call again from the same sender to build balance and check invariant.
        c.addToBalance{value: amount2}();

        // The invariant: contract balance >= sum of balances of all users.
        // Since we only added from one sender, we can check that the contract's balance is at least this user's balance.
        // In M, overflow can make userBalance < sum of sent amounts, breaking the invariant.
        uint256 userBal = c.getBalance(address(this));
        assert(address(c).balance >= userBal);
    }
}

contract InvMutTest {
    C c;
