        require(address(this).balance >= v1 + v2);
        uint256 before = c.getBalance(u);
        c.addToBalance{value: v1}();
        uint256 after = c.getBalance(u);
        c.addToBalance{value: v2}();
        uint256 after2 = c.getBalance(u);
        assert(after >= before && after2 >= after);
    }
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address u, uint256 amount) public payable {
        require(u != address(this) && u != address(c) && amount > 0 && amount <= type(uint256).max - c.getBalance(u));
        uint256 prev = c.getBalance(u);
        c.addToBalance{value: amount}(u);
        assert(c.getBalance(u) == prev + amount);
    }
