pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 initialBalance, uint256 addValue, address caller, address other) public {
        // Bound values to keep in broad admissible domain (prevent overflow in test logic, not contract)
        vm.assume(caller != address(0));
        vm.assume(other != caller);
        initialBalance = bound(initialBalance, 0, type(uint256).max - 1);
        addValue = bound(addValue, 1, type(uint256).max - initialBalance);

        // Set initial balance for the caller via manual state update using low-level cheatcode?
        // We cannot set userBalance directly; we drive through addToBalance to set initial state.
        // Deposit initialBalance for caller first.
        vm.deal(caller, initialBalance);
        vm.prank(caller);
        c.addToBalance{value: initialBalance}();

        // Record pre-state balances
        uint256 preCallerBalance = c.getBalance(caller);
        uint256 preOtherBalance = c.getBalance(other);

        // Now perform the fuzzed addToBalance
        vm.deal(caller, addValue);
        vm.prank(caller);
        c.addToBalance{value: addValue}();

        // Post-state balances
        uint256 postCallerBalance = c.getBalance(caller);
        uint256 postOtherBalance = c.getBalance(other);

        // Assert rule: caller's balance must increase exactly by addValue; others' balances unchanged
        assertTrue(postCallerBalance == preCallerBalance + addValue && postOtherBalance == preOtherBalance);
    }
}

