pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    Attack attacker;

    function setUp() public {
        c = new C();
        attacker = new Attack(c);
        vm.deal(address(attacker), 100 ether);
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount <= 100 ether);
        uint256 snapshot = vm.snapshot();
        try attacker.attack(amount) {
            // should always fail in reference, may succeed in mutant
            vm.revertTo(snapshot);
            assertTrue(false, "attack should revert in reference");
        } catch {
            // expected for reference
            vm.revertTo(snapshot);
            assertTrue(true, "attack reverted as expected in reference");
        }
    }
}

contract Attack {
    C public target;
    uint256 public attackAmount;
    bool public attacking;

    constructor(C _target) {
        target = _target;
    }

    function attack(uint256 amount) external payable {
        require(msg.value == 0, "attack should not receive ether directly");
        attacking = true;
        attackAmount = amount;
        target.addToBalance{value: amount}();
    }

    receive() external payable {
        if (attacking) {
            attacking = false;
            target.addToBalance{value: msg.value}();
        }
    }
}

