pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 reenterAmount) public {
        vm.assume(amount > 0 && amount <= type(uint128).max);
        vm.assume(reenterAmount > 0 && reenterAmount <= amount);
        vm.deal(address(this), amount + reenterAmount);
        ReentrantAttacker attacker = new ReentrantAttacker(c, reenterAmount);

        // Give the attacker some balance in C first
        vm.deal(address(attacker), amount);
        attacker.deposit{value: amount}();

        uint256 preBalance = c.getBalance(address(attacker));
        uint256 preAttackerBalance = address(attacker).balance;

        // Trigger withdrawal which will re-enter addToBalance
        try attacker.attack{value: reenterAmount}() {
            uint256 postBalance = c.getBalance(address(attacker));
            // After attack, the attacker's balance in C should reflect only the reentered deposit,
            // but the reference prevents this via reentrancy guard, keeping it at 0.
            // The invariant: caller's balance after withdrawal is 0 in reference.
            assertTrue(postBalance == 0);
        } catch {
            // Revert is acceptable for reference (guard prevents reentrancy)
            assertTrue(true);
        }
    }
}

contract ReentrantAttacker {
    C target;
    uint256 reenterAmount;
    constructor(C _target, uint256 _reenterAmount) payable {
        target = _target;
        reenterAmount = _reenterAmount;
    }
    function deposit() external payable {
        target.addToBalance{value: msg.value}();
    }
    function attack() external payable {
        target.addToBalance{value: msg.value}();
        target.withdrawBalance();
    }
    receive() external payable {
        if (address(target).balance >= reenterAmount) {
            target.addToBalance{value: reenterAmount}();
        }
    }
}

