import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, uint256 attackerAmount) public {
        // 1. restrict amounts to reasonable range
        amount = bound(amount, 1, 100 ether);
        attackerAmount = bound(attackerAmount, 1, 100 ether);

        // 2. deploy re-entrant attacker helper
        Attacker attacker = new Attacker(c);
        address attackerAddr = address(attacker);

        // 3. set up balances and add to balance for two users
        vm.deal(attackerAddr, attackerAmount);
        vm.prank(attackerAddr);
        c.addToBalance{value: attackerAmount}();

        vm.deal(address(this), amount);
        c.addToBalance{value: amount}();

        // 4. attacker withdraws, triggering reentrancy during withdrawal
        vm.prank(attackerAddr);
        attacker.attack();

        // 5. assert invariant: contract balance equals sum of all userBalance entries
        uint256 contractBalance = address(c).balance;
        uint256 sumBalances = c.getBalance(attackerAddr) + c.getBalance(address(this));
        assertTrue(contractBalance == sumBalances);
    }
}

