contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, bool dummy) public {
        // attacker is a re-entrant caller that calls withdrawBalance when it receives a call
        Attacker attacker = new Attacker();
        vm.assume(amount > 0);
        vm.assume(amount <= 1e36);
        // fund the attacker so it can send ether to c
        vm.deal(address(attacker), amount);
        // give the attacker an initial balance in c so that withdrawBalance will send it funds (triggering re-entrancy)
        vm.prank(address(attacker));
