        // record balances before the call
        uint256 preBalanceAttacker = address(attacker).balance;
        uint256 preBalanceC = address(c).balance;
        uint256 preUserAttacker = c.getBalance(address(attacker));
        // attacker calls addToBalance, which may re-enter via withdrawBalance
        vm.prank(address(attacker));
        c.addToBalance{value: amount}();
        uint256 postUserAttacker = c.getBalance(address(attacker));
        uint256 postBalanceC = address(c).balance;
        uint256 postBalanceAttacker = address(attacker).balance;
        // property: the caller's userBalance and the contract's ether balance both increase by exactly the sent amount
        // (no external funds should be extracted during addToBalance in the reference)
