pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount1, uint256 amount2, address depositor) public {
        // Bound amounts to prevent overflow and ensure non-zero deposits to observe balance changes
        amount1 = bound(amount1, 1, type(uint128).max);
        amount2 = bound(amount2, 1, type(uint128).max);
        vm.assume(depositor != address(0) && depositor != address(this) && depositor != address(c));

        // Fund the depositor
        vm.deal(depositor, amount1 + amount2);

        uint256 initialBalance = c.getBalance(depositor);

        // First deposit
        vm.prank(depositor);
        c.addToBalance{value: amount1}();

        // Second deposit
        vm.prank(depositor);
        c.addToBalance{value: amount2}();

        uint256 finalBalance = c.getBalance(depositor);

        // The reference implementation updates balance incrementally for each call.
        // The mutant permanently locks after the first call, so the second call reverts and balance stays at amount1.
        // The invariant: after two deposits, balance must equal initial + both amounts.
        assertTrue(finalBalance == initialBalance + amount1 + amount2);
    }
}

