contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address actor) public {
        vm.assume(amount > 0 && amount <= address(this).balance);
        vm.assume(actor != address(0) && actor != address(c));
        vm.deal(address(this), amount * 2);
        // Reentrant attacker that calls back into c from its receive
        ReentrantAttacker attacker = new ReentrantAttacker(c);
        // Deposit some ether to the attacker's balance via addToBalance
        vm.prank(address(attacker));
        c.addToBalance{value: amount}();
        // Now trigger a reentrant withdraw that tries to drain more than the balance
        vm.prank(address(attacker));
        attacker.attack(amount);
        // After all calls, the sum of user balances must equal the contract's ether balance
        // The reference contract enforces this, but the buggy version allows reentrant withdrawals
        // that reduce the contract balance without zeroing the user's balance atomically.
        // We cannot sum all balances because mapping is not enumerable, but for a single user
        // the user's balance should not exceed the contract's balance.
        assertTrue(c.getBalance(address(attacker)) <= address(c).balance);
    }
}

