pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        // Bound the deposit amount to a reasonable range; ensure attacker has enough ETH
        amount = bound(amount, 1 ether, 100 ether);
        vm.deal(address(this), amount * 2);

        // Deploy a reentrant attacker that calls withdrawBalance from its receive
        ReentrantAttacker attacker = new ReentrantAttacker(c);
        vm.deal(address(attacker), amount);

        // Attacker deposits via addToBalance; during withdrawBalance -> send -> receive, it reenters withdrawBalance
        attacker.attack{value: amount}();

        // After the attack, the locked_ flag MUST be false in the correct contract
        // (the modifier sets it false after _;). In the buggy version, the modifier
        // never sets locked_=true at entry, so the reentrant call sets it true and
        // the outer call never clears it, leaving locked_ true.
        assertTrue(!c.locked_());
    }
}

contract ReentrantAttacker {
    C public target;
    uint8 private calls;

    constructor(C _target) {
        target = _target;
    }

    function attack() external payable {
        calls = 0;
        target.addToBalance{value: msg.value}();
        target.withdrawBalance();
