import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 initialBalance, uint256 depositAmount) public {
        // bound depositAmount to avoid the sum overflowing and causing an assert in the reference
        // but allow the buggy version to wrap; the fuzzer will find values where initialBalance + depositAmount > type(uint256).max
        vm.assume(initialBalance <= type(uint256).max / 2);
        vm.assume(depositAmount <= type(uint256).max / 2);
        // Set up initial balance by sending ether through addToBalance (no pre-existing balance other than zero)
        // We need to set userBalance[msg.sender] to initialBalance. We can achieve this by first depositing initialBalance.
        // Since initialBalance can be large, we need to fund the account and call addToBalance.
        address actor = address(0x1234);
        vm.deal(actor, initialBalance);
        vm.prank(actor);
        c.addToBalance{value: initialBalance}();
        // Record the balance before the second deposit
        uint256 balanceBefore = c.getBalance(actor);
        // Now perform the deposit of depositAmount
        vm.deal(actor, depositAmount);
        vm.prank(actor);
        c.addToBalance{value: depositAmount}();
        uint256 balanceAfter = c.getBalance(actor);
        // The reference ensures balanceAfter == balanceBefore + depositAmount without overflow (assert in add_uint256)
        // The buggy version wraps on overflow, giving balanceAfter < balanceBefore + depositAmount for some inputs
        // For the reference, if initialBalance + depositAmount > type(uint256).max, the assert in add_uint256 reverts,
        // so the transaction fails and balance remains at balanceBefore. In that case, the rule "balanceAfter == balanceBefore + depositAmount"
        // would not hold for the reference; but the fuzzer will not explore those because the reference reverts and the test won't reach the assertion.
        // However, we want a rule that holds for ALL inputs the reference accepts (i.e., where it does not revert).
        // The reference accepts inputs where initialBalance + depositAmount does not overflow; for those, balanceAfter == balanceBefore + depositAmount.
        // The buggy version does not revert on overflow; instead it wraps, so balanceAfter = (balanceBefore + depositAmount) % 2**256.
        // Thus, the rule "balanceAfter == balanceBefore + depositAmount" holds for the reference on all non-reverting inputs,
        // and fails for the buggy version on some input where overflow occurs.
        // But the fuzzer might generate initialBalance + depositAmount that overflows; the reference will revert, and the test will fail because the call reverts.
        // We can catch the revert and only assert when the call succeeded. However, we only have one assertion.
        // We can use a try/catch to ignore reverts and assert that if it succeeds, then balanceAfter == balanceBefore + depositAmount.
        // The buggy version will succeed on overflow (no revert) and violate the equality.
        // So we wrap the second addToBalance in try/catch.
        // If it fails (reference case for overflow), we do nothing; if it succeeds, we assert equality.
        // The fuzzer will eventually hit an overflow that the buggy version allows, succeeding, and the equality will be false.
        // This satisfies: reference satisfies "if succeeds, balanceAfter == balanceBefore + depositAmount" for all inputs.
        // Buggy: for some input (overflow), it succeeds but equality fails.
        // But we must have exactly one assertTrue. We can do:
        // bool ok;
        // try c.addToBalance{value: depositAmount}() { ok = true; } catch { ok = false; }
        // if (ok) { assertTrue(balanceAfter == balanceBefore + depositAmount); } else { assertTrue(true); } // not a single assert
        // Instead, we can combine: assertTrue(!ok || (balanceAfter == balanceBefore + depositAmount));
        // This holds for reference always: if reference reverts, ok=false, true; if succeeds, equality holds.
        // For buggy: when overflow, ok=true but equality fails, making the whole expression false.
        bool succeeded;
        try c.addToBalance{value: depositAmount}() { succeeded = true; } catch { succeeded = false; }
        balanceAfter = c.getBalance(actor);
        assertTrue(!succeeded || (balanceAfter == balanceBefore + depositAmount));
    }
}

